    "Ambo University was established in 1939 E.C as a school of Agriculture, the first agricultural school in Ethiopia. Passing through various development stages as Ambo Agriculture and Forestry Secondary School, Ambo Institute of Agriculture, Ambo Junior College of Agriculture, Jimma University - Ambo College, Ambo University College, it becomes an autonomous University in 2001 EC.",
