    "Debre Markos University is found in the Northwestern part of Ethiopia at Debre Markos town which is located in the Eastern approximately two kilometers from the central square covering an area of 100 hectares.",
    "Debre Markos town is located 300 kilometers North-West of the capital Addis Ababa and 265 kilometers South-East of Bahir Dar, the capital of the Amhara National Regional State. The University is founded in an area with immense research and investment potentials, suitable weather conditions, and tourist attraction sites. Its foundation stone was laid in January 2005 and inaugurated on 18 November 2007. After the completion of the first phase of the construction, the University began its service in February 2007 admitting the first batch of 760 regular students in the Education Faculty with 53 academics, 34 supporting permanent staff, and 21 contract workers."
