   "about": [
    "Jigjiga University is one of the public higher institutions that was founded in March 2007, along with the Second-Generation universities in Ethiopia. It is located in the emerging town of Jigjiga the capital city of the Ethiopian Somali regional state, 635 kilometers away from Addis Ababa. The University officially started its service with 712 students, 66 and 99 administrative in three faculties in 2007.",
    "In recent years, the intake capacity is increasing from year to year. So currently, it has a total of 21,554 students studying in 57 various academic programs and 627 post-graduate students pursuing in six academic programs. These programs are operating under eight Colleges, three Schools, and an Institute.",
    "To this effect, the university has shown much achievement in education, research, and community service. Last year only, 1888 students are graduated from the different disciplines that is capable of playing a great role in the development of the country.",
    "In it is aim is conducting demand-driven research and communicating relevant research output which is problem-solving and result oriented. Most of this research focuses on pastoral and agro-pastoral studies. The research output communication is one strategic objective that focuses on the adoption and adaptation of locally relevant technology and its transferring and assessing the community awareness on cross-cutting issues. It is also engaging in publicizing different research and related works to the internal and external customers and stakeholders through various means, like media, seminars, symposiums,s and intellectual forums."
   ],
