   "id": "oromia-state-university",
   "name": "Oromia State University",
   "abbr": "OSU",
   "type": "public",
   "website": "http://www.osu.edu.et/",
   "about": [
    "Oromia State University (OSU) is the first regional university in the history of the country, Ethiopia. Oromia State University was established in 2009 E.C through Proclamation No 190/2009 E.C of the Oromia Regional State Administrative Council. The genes of the University go back to1988 E.C when a small training center was informally constituted in Weliso town with the aim of providing short-term training to political cadets and newly recruited public servants of the region. It was formally established as ‘Oromia Management Institute’ in 1992 E.C through Proclamation No. 33/1992 in order to enhance the efficiency and effectiveness of public servants through comprehensive training, consultancy, and research. Pursuant to the changing circumstances and the increasing demands of the region, the institute was upgraded to a college-level in 1997. Subsequently, it was restructured and renamed as ‘Public Service College of Oromia’ through Regulation No. 47/1997.",
    "In recent years, the further increasing demands of the public for efficient services, good governance, equitable development, and the intensified pressure on the regional government necessitated scaling up of the College to University level so as to meet the desperate needs for competent public servants, capable leaders and transformed institutions that can serve the interest of the public. The current ‘Oromia State University has been established as a state-owned higher education institution with the mission of improving the implementation capacity of the regional government and ensuring institutional transformation through education, reform, training and consultancy, research, and community services."
   ],
   "category": "University",
