   "id": "samara-university",
   "name": "Samara University",
   "abbr": "SAU",
   "type": "public",
   "website": "https://www.su.edu.et/",
   "about": [
    "Samara University is a newly established pioneer academic institution located in Ethiopia specifically situated at “Samara” town which is the regional capital of the Afar National Regional State.",
    "The region is endowed with a considerable amount of natural resources which are totally unavailable or rarely available in other parts of the country and even in any part of the world. The University is located with a distance of 1.5kms farther from the Ethio-Djibouti international highway that connects Ethiopia with Djibouti. Samara University is the only university in the world that is situated in the same town as LUCY (the oldest human being) having a distance of 1.5 km in between them. Moreover, it is the only university surrounded by reach and untapped natural resources and a considerable amount of tourist attraction sites that have greater hope and possibility of growth to the region and to the country in general. Geothermal energy, Accumulation of potash and gold, the Awash National park, the fossils of Lucy, the fossils of Kadaba, the Dallol Depression, the Erta ale active volcano, the Afdera Salt production site, Barahle salt production site, and many others are some of the unique natural resources and tourist attraction sites found around samara university."
   ],
   "category": "University",
