   "id": "wolaita-sodo-university",
   "name": "Wolaita Sodo University",
   "abbr": "WSU",
   "type": "public",
   "website": "http://www.wsu.edu.et/",
   "about": [
    "Wolaita Sodo University (WSU) is one of the second-generation public higher institutions in Ethiopia, located in Wolaita Sodo town, 315 km away from the capital Addis Ababa. The university was established on March 24, 2007, G.C. It has been commenced the teaching and learning process by ending its first batch of 801 (609 males and 192 females) students under four facilities and 16 departments.",
    "In the past decades, remarkable and multifarious progress has been registered in terms of quality education delivery, program diversification, campus expansion, and conducting multi-disciplinary research activities. At the end of 2017 G.C. WSU has colorfully celebrated its 10th year anniversary with all the campus community and stakeholders. WSU is a multi-campus university functioning in four premises (Gandaba campus, Otona campus, Boditti, and Tercha campus). The university has also made its own impeccable efforts in extensive renovation and expansion of works to create an intellectually stimulating and enabling environment for teaching, learning, and research endeavors.",
    "WSU is committed to providing undergraduate, graduate, and other specialty programs that enable students to attain their fullest potential intellectually, ethically, and morally. Currently, 58 undergraduate and 43 graduate programs including five doctorate (Ph.D.) degree programs are running under six colleges and four schools. The university delivers courses in regular, evening, weekend, and summer modalities. Students’ enrollment in all programs has shown increment and reaches over 30,000 in 2018/19 G.C.",
    "During the 2017/18 academic year, the academic staff composition is boosted to1313, and over 3113 administrative staff population are voraciously striving to achieve institutional goals. In the previous years, the university also graduated over 24, 000 alumni in undergraduate and graduate programs.",
    "As its core mission, WSU is involved in divergent mainstreaming research and community services and has gained a record of significant achievements. So far, the university has published and disseminated three proceedings and hosted six successive research conferences that point towards the sustainable socio-economic development of the country. WSU established six research centers aiming to create a platform for practical teaching and multi-disciplinary researches.",
    "Laying claim to a global mindset, the university actively partners with other leading higher education institutions and industries partners around the world to provide international opportunities to its students and staff."
   ],
   "category": "University",
   "lat": 6.85775,
   "lng": 37.75785,
   "city": "Sodo",
   "region": "South Ethiopia",
